import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, float, uniform, texture, normalMap, displacementMap, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

const createNode = (config, ctx) => {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Colors from spec
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Create tessellated plane for displacement
  const geometry = new THREE.PlaneGeometry(2, 1.25, 64, 64);

  let material = new MeshStandardNodeMaterial({
    color: colors.surface,
    metalness: 0.45,
    roughness: 0.6,
    clearcoat: 0.15,
    side: THREE.FrontSide
  });

  // Load textures asynchronously and set up displacement
  const texturePromises = [];

  if (config.imageUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        tex.colorSpace = THREE.SRGBColorSpace;
        material.colorNode = texture(tex);
        material.needsUpdate = true;
      }).catch(() => {})
    );
  }

  if (config.depthMapUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
        // TSL displacement: sample depth map and displace along normal
        const dispStrength = uniform(0.08);
        const dispSampler = texture(depthTex);
        const dispUv = uv();
        const dispValue = mix(
          float(0),
          dispSampler.r,
          dispStrength
        );

        // Apply displacement to positionLocal
        material.displaceNode = dispValue;
        material.needsUpdate = true;
      }).catch(() => {})
    );
  }

  const mesh = new THREE.Mesh(geometry, material);
  mesh.receiveShadow = true;
  mesh.castShadow = true;
  group.add(mesh);

  // Apply parallax-scroll primitive if specified
  let primitiveResult = null;
  if (config.cinematicPrimitives?.length > 0) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name === 'parallax-scroll') {
        primitiveResult = ctx.primitives['parallax-scroll'](group, prim.params || { intensity: 0.25 });
        break;
      }
    }
  }

  // Hover interaction: rise-in (translate +0.15 z, power3.out, 0.4s)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    z: group.position.z + 0.15,
    duration: 0.4,
    ease: 'power3.out'
  }, 0);

  const resetTimeline = gsap.timeline({ paused: true });
  resetTimeline.to(group.position, {
    z: 0,
    duration: 0.4,
    ease: 'power3.out'
  }, 0);

  // Click: press-down scale effect
  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(group.scale, {
    x: 0.97,
    y: 0.97,
    duration: 0.12,
    ease: 'back.out'
  }, 0);

  const releaseTimeline = gsap.timeline({ paused: true });
  releaseTimeline.to(group.scale, {
    x: 1,
    y: 1,
    duration: 0.15,
    ease: 'power4.out'
  }, 0);

  // Event handlers
  group.userData.handlers = {
    hover: () => {
      resetTimeline.kill();
      hoverTimeline.restart();
    },
    unhover: () => {
      hoverTimeline.kill();
      resetTimeline.restart();
    },
    click: () => {
      pressTimeline.restart();
      releaseTimeline.delay(0.12).restart();
      ctx.emit('hub-features.select', {});
    }
  };

  // Cleanup
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    resetTimeline.kill();
    pressTimeline.kill();
    releaseTimeline.kill();
    if (primitiveResult?.cleanup) {
      primitiveResult.cleanup();
    }
    geometry.dispose();
    material.dispose();
  };

  return group;
};

export default createNode;
